#include "unity.h"
#include <stdio.h>
#include <string.h>
#include "debug_menu.h"

void setUp(void)   {}
void tearDown(void) {}

/* Shared detector instance reused across the hold tests */
static debug_hold_t hold;

/* Every cursor position in forward order, written out from the spec
 * rather than built from debug_page_items(): the three information
 * pages, Speaker items 0..12, then Faults items 0..4.
 * 3 + 13 + 5 = 21 positions = one full turn of the cursor. */
#define POSITION_COUNT  21U

typedef struct {
    uint8_t page;
    uint8_t item;
} position_t;

static const position_t s_forward[POSITION_COUNT] = {
    { DEBUG_PAGE_SYSTEM,   0U },
    { DEBUG_PAGE_STORAGE,  0U },
    { DEBUG_PAGE_POWER,    0U },
    { DEBUG_PAGE_SPEAKER,  0U }, { DEBUG_PAGE_SPEAKER,  1U },
    { DEBUG_PAGE_SPEAKER,  2U }, { DEBUG_PAGE_SPEAKER,  3U },
    { DEBUG_PAGE_SPEAKER,  4U }, { DEBUG_PAGE_SPEAKER,  5U },
    { DEBUG_PAGE_SPEAKER,  6U }, { DEBUG_PAGE_SPEAKER,  7U },
    { DEBUG_PAGE_SPEAKER,  8U }, { DEBUG_PAGE_SPEAKER,  9U },
    { DEBUG_PAGE_SPEAKER, 10U }, { DEBUG_PAGE_SPEAKER, 11U },
    { DEBUG_PAGE_SPEAKER, 12U },
    { DEBUG_PAGE_FAULTS,   0U }, { DEBUG_PAGE_FAULTS,   1U },
    { DEBUG_PAGE_FAULTS,   2U }, { DEBUG_PAGE_FAULTS,   3U },
    { DEBUG_PAGE_FAULTS,   4U },
};

/* Packs a position as 0xPPII so one assert shows page and item together
 * (e.g. 0x030C = Speaker item 12, 0x0404 = Faults item 4). */
#define POS(page, item)  ((uint16_t)(((unsigned)(page) << 8) | (unsigned)(item)))

/* Helper — position after one detent clockwise from (page, item) */
static uint16_t after_next(uint8_t page, uint8_t item)
{
    debug_cursor_next(&page, &item);
    return POS(page, item);
}

/* Helper — position after one detent counter-clockwise from (page, item) */
static uint16_t after_prev(uint8_t page, uint8_t item)
{
    debug_cursor_prev(&page, &item);
    return POS(page, item);
}

/* Helper — every name is drawn as-is, so it must be non-empty and short */
static void assert_name_fits(const char *name)
{
    TEST_ASSERT_NOT_NULL(name);
    TEST_ASSERT_TRUE(strlen(name) > 0U);
    TEST_ASSERT_LESS_OR_EQUAL_UINT(DEBUG_NAME_MAX, strlen(name));
}

/* Helper — BACK held on Home at every 10 ms scan from 'from' to 'to' ms
 * (both included); returns how many times the detector fired. */
static unsigned hold_on_home(uint32_t from, uint32_t to)
{
    unsigned fires = 0U;
    for (uint32_t t = from; t <= to; t += 10U) {
        fires += debug_hold_update(&hold, 1U, 1U, t);
    }
    return fires;
}

/* ═══════════════════════════════════════════════════════════════════════
 * GROUP A — Pages and item counts
 * ═══════════════════════════════════════════════════════════════════════ */

void test_A01_items_per_page(void)
{
    TEST_ASSERT_EQUAL_UINT8(1U,  debug_page_items(DEBUG_PAGE_SYSTEM));
    TEST_ASSERT_EQUAL_UINT8(1U,  debug_page_items(DEBUG_PAGE_STORAGE));
    TEST_ASSERT_EQUAL_UINT8(1U,  debug_page_items(DEBUG_PAGE_POWER));
    TEST_ASSERT_EQUAL_UINT8(13U, debug_page_items(DEBUG_PAGE_SPEAKER));
    TEST_ASSERT_EQUAL_UINT8(5U,  debug_page_items(DEBUG_PAGE_FAULTS));
}

void test_A02_invalid_page_has_no_items(void)
{
    TEST_ASSERT_EQUAL_UINT8(0U, debug_page_items(DEBUG_PAGE_COUNT));
    TEST_ASSERT_EQUAL_UINT8(0U, debug_page_items(200U));
    TEST_ASSERT_EQUAL_UINT8(0U, debug_page_items(255U));
}

void test_A03_count_defines_match_the_pages(void)
{
    /* The glue draws the lists by looping up to these defines */
    TEST_ASSERT_EQUAL_INT(5, DEBUG_PAGE_COUNT);
    TEST_ASSERT_EQUAL_UINT(DEBUG_SPEAKER_PATTERNS + DEBUG_SPEAKER_TUNES,
                           DEBUG_SPEAKER_ITEMS);
    TEST_ASSERT_EQUAL_UINT(DEBUG_SPEAKER_ITEMS,
                           debug_page_items(DEBUG_PAGE_SPEAKER));
    TEST_ASSERT_EQUAL_UINT(DEBUG_FAULT_ITEMS,
                           debug_page_items(DEBUG_PAGE_FAULTS));
}

void test_A04_positions_add_up_to_one_full_turn(void)
{
    unsigned total = 0U;
    for (uint8_t p = 0U; p < (uint8_t)DEBUG_PAGE_COUNT; p++) {
        total += debug_page_items(p);
    }
    TEST_ASSERT_EQUAL_UINT(POSITION_COUNT, total);
}

/* ═══════════════════════════════════════════════════════════════════════
 * GROUP B — Cursor: full walks, page changes and wrap-around
 * ═══════════════════════════════════════════════════════════════════════ */

void test_B01_forward_walk_visits_every_position_in_order(void)
{
    uint8_t page = DEBUG_PAGE_SYSTEM;
    uint8_t item = 0U;
    char    msg[24];

    /* Step n lands on position n; step 21 is back on System */
    for (unsigned step = 1U; step <= POSITION_COUNT; step++) {
        const position_t *want = &s_forward[step % POSITION_COUNT];
        debug_cursor_next(&page, &item);
        snprintf(msg, sizeof(msg), "step %u", step);
        TEST_ASSERT_EQUAL_HEX16_MESSAGE(POS(want->page, want->item),
                                        POS(page, item), msg);
    }
    TEST_ASSERT_EQUAL_HEX16(POS(DEBUG_PAGE_SYSTEM, 0U), POS(page, item));
}

void test_B02_backward_walk_is_exact_reverse(void)
{
    uint8_t page = DEBUG_PAGE_SYSTEM;
    uint8_t item = 0U;
    char    msg[24];

    /* Step 1 lands on the last Faults item, step 21 is back on System */
    for (unsigned step = 1U; step <= POSITION_COUNT; step++) {
        const position_t *want = &s_forward[POSITION_COUNT - step];
        debug_cursor_prev(&page, &item);
        snprintf(msg, sizeof(msg), "step %u", step);
        TEST_ASSERT_EQUAL_HEX16_MESSAGE(POS(want->page, want->item),
                                        POS(page, item), msg);
    }
    TEST_ASSERT_EQUAL_HEX16(POS(DEBUG_PAGE_SYSTEM, 0U), POS(page, item));
}

void test_B03_info_pages_change_page_on_every_detent(void)
{
    TEST_ASSERT_EQUAL_HEX16(POS(DEBUG_PAGE_STORAGE, 0U), after_next(DEBUG_PAGE_SYSTEM,  0U));
    TEST_ASSERT_EQUAL_HEX16(POS(DEBUG_PAGE_POWER,   0U), after_next(DEBUG_PAGE_STORAGE, 0U));
    TEST_ASSERT_EQUAL_HEX16(POS(DEBUG_PAGE_SPEAKER, 0U), after_next(DEBUG_PAGE_POWER,   0U));
    TEST_ASSERT_EQUAL_HEX16(POS(DEBUG_PAGE_STORAGE, 0U), after_prev(DEBUG_PAGE_POWER,   0U));
    TEST_ASSERT_EQUAL_HEX16(POS(DEBUG_PAGE_SYSTEM,  0U), after_prev(DEBUG_PAGE_STORAGE, 0U));
}

void test_B04_list_pages_move_item_by_item(void)
{
    TEST_ASSERT_EQUAL_HEX16(POS(DEBUG_PAGE_SPEAKER, 1U),  after_next(DEBUG_PAGE_SPEAKER, 0U));
    TEST_ASSERT_EQUAL_HEX16(POS(DEBUG_PAGE_SPEAKER, 10U), after_next(DEBUG_PAGE_SPEAKER, 9U));
    TEST_ASSERT_EQUAL_HEX16(POS(DEBUG_PAGE_SPEAKER, 11U), after_prev(DEBUG_PAGE_SPEAKER, 12U));
    TEST_ASSERT_EQUAL_HEX16(POS(DEBUG_PAGE_FAULTS,  3U),  after_next(DEBUG_PAGE_FAULTS,  2U));
    TEST_ASSERT_EQUAL_HEX16(POS(DEBUG_PAGE_FAULTS,  0U),  after_prev(DEBUG_PAGE_FAULTS,  1U));
}

void test_B05_next_past_last_speaker_item_goes_to_faults_item_0(void)
{
    TEST_ASSERT_EQUAL_HEX16(POS(DEBUG_PAGE_FAULTS, 0U), after_next(DEBUG_PAGE_SPEAKER, 12U));
}

void test_B06_prev_from_speaker_item_0_lands_on_power(void)
{
    TEST_ASSERT_EQUAL_HEX16(POS(DEBUG_PAGE_POWER, 0U), after_prev(DEBUG_PAGE_SPEAKER, 0U));
}

void test_B07_prev_from_faults_item_0_lands_on_last_speaker_item(void)
{
    TEST_ASSERT_EQUAL_HEX16(POS(DEBUG_PAGE_SPEAKER, 12U), after_prev(DEBUG_PAGE_FAULTS, 0U));
}

void test_B08_prev_from_system_wraps_to_last_faults_item(void)
{
    TEST_ASSERT_EQUAL_HEX16(POS(DEBUG_PAGE_FAULTS, 4U), after_prev(DEBUG_PAGE_SYSTEM, 0U));
}

void test_B09_next_from_last_faults_item_wraps_to_system(void)
{
    TEST_ASSERT_EQUAL_HEX16(POS(DEBUG_PAGE_SYSTEM, 0U), after_next(DEBUG_PAGE_FAULTS, 4U));
}

void test_B10_one_detent_back_undoes_one_detent_forward(void)
{
    /* From every position, next-then-prev and prev-then-next both come
     * back to the start: the two directions are exact inverses. */
    for (unsigned n = 0U; n < POSITION_COUNT; n++) {
        uint16_t start = POS(s_forward[n].page, s_forward[n].item);
        uint8_t  page  = s_forward[n].page;
        uint8_t  item  = s_forward[n].item;

        debug_cursor_next(&page, &item);
        debug_cursor_prev(&page, &item);
        TEST_ASSERT_EQUAL_HEX16(start, POS(page, item));

        debug_cursor_prev(&page, &item);
        debug_cursor_next(&page, &item);
        TEST_ASSERT_EQUAL_HEX16(start, POS(page, item));
    }
}

/* ═══════════════════════════════════════════════════════════════════════
 * GROUP C — Speaker items: test pattern / tune mapping
 * Pattern index 0..9 = Tom_Test_t order from TOM_TEST_SWEEP_100;
 * tune index 0..2 = TOM_TUNE_STARTUP / CRITICAL / FAULT.
 * ═══════════════════════════════════════════════════════════════════════ */

void test_C01_items_0_to_9_are_patterns_in_order(void)
{
    for (uint8_t i = 0U; i < 10U; i++) {
        TEST_ASSERT_EQUAL_UINT8(0U,               debug_speaker_is_tune(i));
        TEST_ASSERT_EQUAL_UINT8(i,                debug_speaker_pattern_index(i));
        TEST_ASSERT_EQUAL_UINT8(DEBUG_INDEX_NONE, debug_speaker_tune_index(i));
    }
}

void test_C02_items_10_to_12_are_tunes(void)
{
    for (uint8_t i = 10U; i <= 12U; i++) {
        TEST_ASSERT_EQUAL_UINT8(1U,               debug_speaker_is_tune(i));
        TEST_ASSERT_EQUAL_UINT8(DEBUG_INDEX_NONE, debug_speaker_pattern_index(i));
    }
    TEST_ASSERT_EQUAL_UINT8(0U, debug_speaker_tune_index(10U));   /* startup    */
    TEST_ASSERT_EQUAL_UINT8(1U, debug_speaker_tune_index(11U));   /* critical   */
    TEST_ASSERT_EQUAL_UINT8(2U, debug_speaker_tune_index(12U));   /* fault beep */
}

void test_C03_boundaries_9_10_12_13(void)
{
    /* 9 = last pattern (right only), 10 = first tune, 12 = last tune,
     * 13 = first item past the end of the list */
    TEST_ASSERT_EQUAL_UINT8(9U,               debug_speaker_pattern_index(9U));
    TEST_ASSERT_EQUAL_UINT8(0U,               debug_speaker_is_tune(9U));
    TEST_ASSERT_EQUAL_UINT8(DEBUG_INDEX_NONE, debug_speaker_tune_index(9U));
    TEST_ASSERT_EQUAL_UINT8(1U,               debug_speaker_is_tune(10U));
    TEST_ASSERT_EQUAL_UINT8(DEBUG_INDEX_NONE, debug_speaker_pattern_index(10U));
    TEST_ASSERT_EQUAL_UINT8(0U,               debug_speaker_tune_index(10U));
    TEST_ASSERT_EQUAL_UINT8(1U,               debug_speaker_is_tune(12U));
    TEST_ASSERT_EQUAL_UINT8(2U,               debug_speaker_tune_index(12U));
    TEST_ASSERT_EQUAL_UINT8(0U,               debug_speaker_is_tune(13U));
    TEST_ASSERT_EQUAL_UINT8(DEBUG_INDEX_NONE, debug_speaker_pattern_index(13U));
    TEST_ASSERT_EQUAL_UINT8(DEBUG_INDEX_NONE, debug_speaker_tune_index(13U));
}

void test_C04_out_of_range_items_are_neither(void)
{
    static const uint8_t bad[] = { 13U, 14U, 100U, 254U, 255U };
    for (unsigned n = 0U; n < sizeof(bad); n++) {
        TEST_ASSERT_EQUAL_UINT8(0U,               debug_speaker_is_tune(bad[n]));
        TEST_ASSERT_EQUAL_UINT8(DEBUG_INDEX_NONE, debug_speaker_pattern_index(bad[n]));
        TEST_ASSERT_EQUAL_UINT8(DEBUG_INDEX_NONE, debug_speaker_tune_index(bad[n]));
    }
}

/* ═══════════════════════════════════════════════════════════════════════
 * GROUP D — Faults items: actions and SOC override values
 * Outputs start as junk so a missing write shows up.
 * ═══════════════════════════════════════════════════════════════════════ */

void test_D01_storage_fault_item(void)
{
    uint8_t  soc  = 0xAAU;
    uint16_t secs = 0xBEEFU;
    TEST_ASSERT_EQUAL(DEBUG_FAULT_ACT_STORAGE, debug_fault_item_action(0U, &soc, &secs));
    TEST_ASSERT_EQUAL_UINT8(0U, soc);
    TEST_ASSERT_EQUAL_UINT16(0U, secs);
}

void test_D02_battery_low_item_overrides_25_pct_for_300_s(void)
{
    uint8_t  soc  = 0xAAU;
    uint16_t secs = 0xBEEFU;
    TEST_ASSERT_EQUAL(DEBUG_FAULT_ACT_SOC_OVERRIDE, debug_fault_item_action(1U, &soc, &secs));
    TEST_ASSERT_EQUAL_UINT8(25U, soc);
    TEST_ASSERT_EQUAL_UINT16(300U, secs);
}

void test_D03_battery_crit_item_overrides_8_pct_for_300_s(void)
{
    uint8_t  soc  = 0xAAU;
    uint16_t secs = 0xBEEFU;
    TEST_ASSERT_EQUAL(DEBUG_FAULT_ACT_SOC_OVERRIDE, debug_fault_item_action(2U, &soc, &secs));
    TEST_ASSERT_EQUAL_UINT8(8U, soc);
    TEST_ASSERT_EQUAL_UINT16(300U, secs);
}

void test_D04_battery_ok_item_overrides_60_pct_for_65535_s(void)
{
    /* The longest override: one push lasts a whole demo (about 18 h). */
    uint8_t  soc  = 0xAAU;
    uint16_t secs = 0xBEEFU;
    TEST_ASSERT_EQUAL(DEBUG_FAULT_ACT_SOC_OVERRIDE, debug_fault_item_action(3U, &soc, &secs));
    TEST_ASSERT_EQUAL_UINT8(60U, soc);
    TEST_ASSERT_EQUAL_UINT16(65535U, secs);
}

void test_D05_clear_item_sends_soc_0_for_0_s(void)
{
    uint8_t  soc  = 0xAAU;
    uint16_t secs = 0xBEEFU;
    TEST_ASSERT_EQUAL(DEBUG_FAULT_ACT_CLEAR_OVERRIDE, debug_fault_item_action(4U, &soc, &secs));
    TEST_ASSERT_EQUAL_UINT8(0U, soc);
    TEST_ASSERT_EQUAL_UINT16(0U, secs);
}

void test_D06_out_of_range_item_does_nothing(void)
{
    static const uint8_t bad[] = { 5U, 6U, 200U, 255U };
    for (unsigned n = 0U; n < sizeof(bad); n++) {
        uint8_t  soc  = 0xAAU;
        uint16_t secs = 0xBEEFU;
        TEST_ASSERT_EQUAL(DEBUG_FAULT_ACT_NONE, debug_fault_item_action(bad[n], &soc, &secs));
        TEST_ASSERT_EQUAL_UINT8(0U, soc);
        TEST_ASSERT_EQUAL_UINT16(0U, secs);
    }
}

void test_D07_null_outputs_still_return_the_action(void)
{
    uint8_t  soc  = 0U;
    uint16_t secs = 0U;
    TEST_ASSERT_EQUAL(DEBUG_FAULT_ACT_STORAGE,        debug_fault_item_action(0U, NULL, NULL));
    TEST_ASSERT_EQUAL(DEBUG_FAULT_ACT_SOC_OVERRIDE,   debug_fault_item_action(2U, NULL, NULL));
    TEST_ASSERT_EQUAL(DEBUG_FAULT_ACT_SOC_OVERRIDE,   debug_fault_item_action(2U, &soc, NULL));
    TEST_ASSERT_EQUAL_UINT8(8U, soc);
    TEST_ASSERT_EQUAL(DEBUG_FAULT_ACT_SOC_OVERRIDE,   debug_fault_item_action(2U, NULL, &secs));
    TEST_ASSERT_EQUAL_UINT16(300U, secs);
    TEST_ASSERT_EQUAL(DEBUG_FAULT_ACT_CLEAR_OVERRIDE, debug_fault_item_action(4U, NULL, NULL));
    TEST_ASSERT_EQUAL(DEBUG_FAULT_ACT_NONE,           debug_fault_item_action(9U, NULL, NULL));
}

void test_D08_soc_defines_carry_the_agreed_values(void)
{
    TEST_ASSERT_EQUAL_UINT(25U,  DEBUG_SOC_LOW_PCT);
    TEST_ASSERT_EQUAL_UINT(8U,   DEBUG_SOC_CRIT_PCT);
    TEST_ASSERT_EQUAL_UINT(60U,  DEBUG_SOC_OK_PCT);
    TEST_ASSERT_EQUAL_UINT(300U, DEBUG_SOC_OVERRIDE_S);
    TEST_ASSERT_EQUAL_UINT(65535U, DEBUG_SOC_OK_OVERRIDE_S);   /* uint16_t seconds maximum */
}

/* ═══════════════════════════════════════════════════════════════════════
 * GROUP E — Page titles and item names
 * ═══════════════════════════════════════════════════════════════════════ */

void test_E01_page_titles(void)
{
    TEST_ASSERT_EQUAL_STRING("System",          debug_page_title(DEBUG_PAGE_SYSTEM));
    TEST_ASSERT_EQUAL_STRING("Storage",         debug_page_title(DEBUG_PAGE_STORAGE));
    TEST_ASSERT_EQUAL_STRING("Battery / power", debug_page_title(DEBUG_PAGE_POWER));
    TEST_ASSERT_EQUAL_STRING("Speaker test",    debug_page_title(DEBUG_PAGE_SPEAKER));
    TEST_ASSERT_EQUAL_STRING("Fault injection", debug_page_title(DEBUG_PAGE_FAULTS));
}

void test_E02_speaker_item_names(void)
{
    static const char *const want[13] = {
        "Sweep 100 Hz", "Sweep 200 Hz", "Sweep 500 Hz", "Sweep 1 kHz",
        "Sweep 2 kHz",  "Sweep 5 kHz",  "Sweep 8 kHz",  "Sweep 10 kHz",
        "Left only 1 kHz", "Right only 1 kHz",
        "Tune: startup", "Tune: critical", "Tune: fault beep",
    };
    for (uint8_t i = 0U; i < 13U; i++) {
        TEST_ASSERT_EQUAL_STRING(want[i], debug_speaker_item_name(i));
    }
}

void test_E03_fault_item_names(void)
{
    TEST_ASSERT_EQUAL_STRING("Storage fault",   debug_fault_item_name(0U));
    TEST_ASSERT_EQUAL_STRING("Battery LOW 25%", debug_fault_item_name(1U));
    TEST_ASSERT_EQUAL_STRING("Battery CRIT 8%", debug_fault_item_name(2U));
    TEST_ASSERT_EQUAL_STRING("Battery OK 60%",  debug_fault_item_name(3U));
    TEST_ASSERT_EQUAL_STRING("Clear overrides", debug_fault_item_name(4U));
}

void test_E04_out_of_range_names_are_question_mark(void)
{
    TEST_ASSERT_EQUAL_STRING("?", debug_page_title(DEBUG_PAGE_COUNT));
    TEST_ASSERT_EQUAL_STRING("?", debug_page_title(255U));
    TEST_ASSERT_EQUAL_STRING("?", debug_speaker_item_name(13U));
    TEST_ASSERT_EQUAL_STRING("?", debug_speaker_item_name(255U));
    TEST_ASSERT_EQUAL_STRING("?", debug_fault_item_name(5U));
    TEST_ASSERT_EQUAL_STRING("?", debug_fault_item_name(255U));
}

void test_E05_every_name_fits_16_chars(void)
{
    /* A size-1 debug row is 40 characters on the portrait panel. 16 keeps
     * the title row ("DEBUG 5/5 <title>   BACK = exit") and the list rows
     * ("> <name, padded to 16> SOC 60 % for 65535 s") within it. */
    for (uint8_t p = 0U; p < (uint8_t)DEBUG_PAGE_COUNT; p++) {
        assert_name_fits(debug_page_title(p));
    }
    for (uint8_t i = 0U; i < DEBUG_SPEAKER_ITEMS; i++) {
        assert_name_fits(debug_speaker_item_name(i));
    }
    for (uint8_t i = 0U; i < DEBUG_FAULT_ITEMS; i++) {
        assert_name_fits(debug_fault_item_name(i));
    }
}

void test_E06_battery_names_match_their_soc_values(void)
{
    /* The names spell the percentage out: if a DEBUG_SOC_* value changes,
     * its name must change with it. */
    unsigned checked = 0U;
    for (uint8_t i = 0U; i < DEBUG_FAULT_ITEMS; i++) {
        uint8_t soc = 0U;
        if (debug_fault_item_action(i, &soc, NULL) == DEBUG_FAULT_ACT_SOC_OVERRIDE) {
            char pct[8];
            snprintf(pct, sizeof(pct), " %u%%", (unsigned)soc);
            TEST_ASSERT_NOT_NULL(strstr(debug_fault_item_name(i), pct));
            checked++;
        }
    }
    TEST_ASSERT_EQUAL_UINT(3U, checked);
}

/* ═══════════════════════════════════════════════════════════════════════
 * GROUP F — BACK-hold detector
 * Fires once per press, after 2 s held continuously with every update on
 * Home; one update off Home uses the press up until it is released.
 * Times start at 1000 ms so tick 0 never looks like a special value.
 * ═══════════════════════════════════════════════════════════════════════ */

void test_F01_init_clears_state(void)
{
    hold.down     = 1U;
    hold.fired    = 1U;
    hold.since_ms = 1234U;
    debug_hold_init(&hold);
    TEST_ASSERT_EQUAL_UINT8(0U, hold.down);
    TEST_ASSERT_EQUAL_UINT8(0U, hold.fired);
    TEST_ASSERT_EQUAL_UINT32(0U, hold.since_ms);
}

void test_F02_released_button_never_fires(void)
{
    debug_hold_init(&hold);
    TEST_ASSERT_EQUAL_UINT8(0U, debug_hold_update(&hold, 0U, 1U, 1000U));
    TEST_ASSERT_EQUAL_UINT8(0U, debug_hold_update(&hold, 0U, 1U, 60000U));
}

void test_F03_held_1999_ms_does_not_fire(void)
{
    debug_hold_init(&hold);
    TEST_ASSERT_EQUAL_UINT8(0U, debug_hold_update(&hold, 1U, 1U, 1000U));   /* press edge */
    TEST_ASSERT_EQUAL_UINT8(0U, debug_hold_update(&hold, 1U, 1U, 2000U));
    TEST_ASSERT_EQUAL_UINT8(0U, debug_hold_update(&hold, 1U, 1U, 2999U));   /* 1999 ms    */
}

void test_F04_held_2000_ms_fires(void)
{
    debug_hold_init(&hold);
    TEST_ASSERT_EQUAL_UINT8(0U, debug_hold_update(&hold, 1U, 1U, 1000U));
    TEST_ASSERT_EQUAL_UINT8(1U, debug_hold_update(&hold, 1U, 1U, 3000U));   /* 2000 ms    */
}

void test_F05_fires_only_once_per_press(void)
{
    debug_hold_init(&hold);
    (void)debug_hold_update(&hold, 1U, 1U, 1000U);
    TEST_ASSERT_EQUAL_UINT8(1U, debug_hold_update(&hold, 1U, 1U, 3000U));
    TEST_ASSERT_EQUAL_UINT8(0U, debug_hold_update(&hold, 1U, 1U, 3010U));
    TEST_ASSERT_EQUAL_UINT8(0U, debug_hold_update(&hold, 1U, 1U, 5000U));
    TEST_ASSERT_EQUAL_UINT8(0U, debug_hold_update(&hold, 1U, 1U, 60000U));
}

void test_F06_does_not_fire_off_home(void)
{
    debug_hold_init(&hold);
    (void)debug_hold_update(&hold, 1U, 0U, 1000U);
    TEST_ASSERT_EQUAL_UINT8(0U, debug_hold_update(&hold, 1U, 0U, 3000U));
    TEST_ASSERT_EQUAL_UINT8(0U, debug_hold_update(&hold, 1U, 0U, 10000U));
}

void test_F07_release_resets_so_a_second_hold_fires_again(void)
{
    debug_hold_init(&hold);
    (void)debug_hold_update(&hold, 1U, 1U, 1000U);
    TEST_ASSERT_EQUAL_UINT8(1U, debug_hold_update(&hold, 1U, 1U, 3000U));
    TEST_ASSERT_EQUAL_UINT8(0U, debug_hold_update(&hold, 0U, 1U, 3500U));   /* release   */
    TEST_ASSERT_EQUAL_UINT8(0U, debug_hold_update(&hold, 1U, 1U, 4000U));   /* new press */
    TEST_ASSERT_EQUAL_UINT8(0U, debug_hold_update(&hold, 1U, 1U, 5999U));
    TEST_ASSERT_EQUAL_UINT8(1U, debug_hold_update(&hold, 1U, 1U, 6000U));
}

void test_F08_a_release_mid_hold_restarts_the_count(void)
{
    /* "Continuously": 1.9 s, a release, then 0.1 s is not a 2 s hold */
    debug_hold_init(&hold);
    (void)debug_hold_update(&hold, 1U, 1U, 1000U);
    (void)debug_hold_update(&hold, 0U, 1U, 2900U);
    (void)debug_hold_update(&hold, 1U, 1U, 2910U);                           /* new press edge */
    TEST_ASSERT_EQUAL_UINT8(0U, debug_hold_update(&hold, 1U, 1U, 3000U));   /* 2 s after the first */
    TEST_ASSERT_EQUAL_UINT8(0U, debug_hold_update(&hold, 1U, 1U, 4909U));
    TEST_ASSERT_EQUAL_UINT8(1U, debug_hold_update(&hold, 1U, 1U, 4910U));
}

void test_F09_press_started_off_home_never_fires(void)
{
    /* BACK pressed on the Play screen: its own press edge takes the UI
     * Home a scan (10 ms) later, but this press was not all on Home, so it
     * never opens the debug screen, however long it is held. */
    debug_hold_init(&hold);
    TEST_ASSERT_EQUAL_UINT8(0U, debug_hold_update(&hold, 1U, 0U, 1000U));   /* on Play  */
    TEST_ASSERT_EQUAL_UINT(0U, hold_on_home(1010U, 60000U));                /* now Home */
}

void test_F10_fault_screen_part_way_through_a_hold_never_fires(void)
{
    /* Held on Home for 1.99 s, then a fault screen opens over Home; its
     * ~0.27 s draw puts the first update on it past the 2 s mark. A touch
     * closes it while BACK is still held: Home is back, but the hold left
     * it part-way, so it never fires. */
    debug_hold_init(&hold);
    TEST_ASSERT_EQUAL_UINT(0U, hold_on_home(1000U, 2990U));                 /* 1.99 s on Home */
    TEST_ASSERT_EQUAL_UINT8(0U, debug_hold_update(&hold, 1U, 0U, 3270U));   /* fault screen   */
    TEST_ASSERT_EQUAL_UINT8(0U, debug_hold_update(&hold, 1U, 0U, 3580U));
    TEST_ASSERT_EQUAL_UINT(0U, hold_on_home(3880U, 10000U));                /* Home again     */
}

void test_F11_tick_wraparound(void)
{
    /* Press 1000 ms before the 32-bit tick wraps to 0. A naive
     * "now >= since + 2000" would overflow and fire at 0xFFFFFFFF. */
    debug_hold_init(&hold);
    TEST_ASSERT_EQUAL_UINT8(0U, debug_hold_update(&hold, 1U, 1U, 0xFFFFFC18U));
    TEST_ASSERT_EQUAL_UINT8(0U, debug_hold_update(&hold, 1U, 1U, 0xFFFFFFFFU));  /*  999 ms */
    TEST_ASSERT_EQUAL_UINT8(0U, debug_hold_update(&hold, 1U, 1U, 999U));         /* 1999 ms */
    TEST_ASSERT_EQUAL_UINT8(1U, debug_hold_update(&hold, 1U, 1U, 1000U));        /* 2000 ms */
}

void test_F12_any_non_zero_level_counts_as_true(void)
{
    debug_hold_init(&hold);
    (void)debug_hold_update(&hold, 2U, 7U, 1000U);
    TEST_ASSERT_EQUAL_UINT8(1U, debug_hold_update(&hold, 0x80U, 0xFFU, 3000U));
}

void test_F13_zeroed_detector_works_without_init(void)
{
    /* The glue may rely on static zero-initialisation instead of init */
    memset(&hold, 0, sizeof(hold));
    (void)debug_hold_update(&hold, 1U, 1U, 1000U);
    TEST_ASSERT_EQUAL_UINT8(1U, debug_hold_update(&hold, 1U, 1U, 3000U));
}

void test_F14_null_detector_no_crash(void)
{
    debug_hold_init(NULL);
    TEST_ASSERT_EQUAL_UINT8(0U, debug_hold_update(NULL, 1U, 1U, 5000U));
}

void test_F15_back_that_leaves_the_debug_screen_never_reopens_it(void)
{
    /* The glue works out on_home before it handles the scan's events, so
     * the short BACK that leaves the debug screen is still off Home at its
     * first update; Home is then drawn (~0.3 s) and BACK stays down. The
     * BACK that closes a fault screen shown over Home (e.g. "Gauge not
     * found" at boot) gives the detector the same sequence. */
    debug_hold_init(&hold);
    TEST_ASSERT_EQUAL_UINT8(0U, debug_hold_update(&hold, 1U, 0U, 1000U));   /* on DEBUG */
    TEST_ASSERT_EQUAL_UINT(0U, hold_on_home(1300U, 10000U));                /* Home     */
}

void test_F16_used_up_press_then_a_fresh_2_s_hold_on_home_fires(void)
{
    /* A used-up press only lasts until release: let go of BACK, hold it
     * again on Home, and the debug screen opens 2 s later as usual. */
    debug_hold_init(&hold);
    (void)debug_hold_update(&hold, 1U, 0U, 1000U);                          /* off Home  */
    TEST_ASSERT_EQUAL_UINT(0U, hold_on_home(1300U, 4000U));
    TEST_ASSERT_EQUAL_UINT8(0U, debug_hold_update(&hold, 0U, 1U, 4010U));   /* release   */
    TEST_ASSERT_EQUAL_UINT(0U, hold_on_home(5000U, 6990U));                 /* 1990 ms   */
    TEST_ASSERT_EQUAL_UINT8(1U, debug_hold_update(&hold, 1U, 1U, 7000U));   /* 2000 ms   */
    TEST_ASSERT_EQUAL_UINT8(0U, debug_hold_update(&hold, 1U, 1U, 7010U));   /* once only */
}

void test_F17_one_update_off_home_mid_hold_never_fires(void)
{
    /* Every update must be on Home: a single scan off Home in the middle
     * of an otherwise on-Home hold uses the press up. */
    debug_hold_init(&hold);
    TEST_ASSERT_EQUAL_UINT(0U, hold_on_home(1000U, 1990U));
    TEST_ASSERT_EQUAL_UINT8(0U, debug_hold_update(&hold, 1U, 0U, 2000U));   /* one scan off Home */
    TEST_ASSERT_EQUAL_UINT(0U, hold_on_home(2010U, 10000U));
}

/* ═══════════════════════════════════════════════════════════════════════
 * GROUP G — NULL safety and out-of-range clamping
 * ═══════════════════════════════════════════════════════════════════════ */

void test_G01_cursor_null_pointers_change_nothing(void)
{
    uint8_t page = DEBUG_PAGE_SPEAKER;
    uint8_t item = 5U;

    debug_cursor_next(NULL, &item);
    debug_cursor_next(&page, NULL);
    debug_cursor_prev(NULL, &item);
    debug_cursor_prev(&page, NULL);
    debug_cursor_next(NULL, NULL);
    debug_cursor_prev(NULL, NULL);
    TEST_ASSERT_EQUAL_HEX16(POS(DEBUG_PAGE_SPEAKER, 5U), POS(page, item));
}

void test_G02_out_of_range_page_is_clamped_to_last_page_first(void)
{
    /* Page 200 -> Faults item 0 -> next = Faults item 1 */
    TEST_ASSERT_EQUAL_HEX16(POS(DEBUG_PAGE_FAULTS,  1U),  after_next(200U, 0U));
    /* Page 5 -> Faults item 0 -> prev = last Speaker item */
    TEST_ASSERT_EQUAL_HEX16(POS(DEBUG_PAGE_SPEAKER, 12U), after_prev(DEBUG_PAGE_COUNT, 0U));
    /* Page 255 item 255 -> Faults item 4 -> next wraps to System */
    TEST_ASSERT_EQUAL_HEX16(POS(DEBUG_PAGE_SYSTEM,  0U),  after_next(255U, 255U));
}

void test_G03_out_of_range_item_is_clamped_to_last_item_first(void)
{
    TEST_ASSERT_EQUAL_HEX16(POS(DEBUG_PAGE_FAULTS,  0U),  after_next(DEBUG_PAGE_SPEAKER, 99U));
    TEST_ASSERT_EQUAL_HEX16(POS(DEBUG_PAGE_SPEAKER, 11U), after_prev(DEBUG_PAGE_SPEAKER, 99U));
    TEST_ASSERT_EQUAL_HEX16(POS(DEBUG_PAGE_STORAGE, 0U),  after_next(DEBUG_PAGE_SYSTEM,  7U));
    TEST_ASSERT_EQUAL_HEX16(POS(DEBUG_PAGE_FAULTS,  4U),  after_prev(DEBUG_PAGE_SYSTEM,  7U));
    TEST_ASSERT_EQUAL_HEX16(POS(DEBUG_PAGE_SYSTEM,  0U),  after_next(DEBUG_PAGE_FAULTS,  255U));
}

