    /* Group F — BACK-hold detector */
    RUN_TEST(test_F01_init_clears_state);
    RUN_TEST(test_F02_released_button_never_fires);
    RUN_TEST(test_F03_held_1999_ms_does_not_fire);
    RUN_TEST(test_F04_held_2000_ms_fires);
    RUN_TEST(test_F05_fires_only_once_per_press);
    RUN_TEST(test_F06_does_not_fire_off_home);
    RUN_TEST(test_F07_release_resets_so_a_second_hold_fires_again);
    RUN_TEST(test_F08_a_release_mid_hold_restarts_the_count);
    RUN_TEST(test_F09_press_started_off_home_never_fires);
    RUN_TEST(test_F10_fault_screen_part_way_through_a_hold_never_fires);
